        let row = locals[cdt][cdn];
        if (!row.item_code) return;

        const existing_suppliers = frm.doc.suppliers.map(s => s.supplier);

        frappe.call({
            method: "gormsolutions_mobile_app.custom_api.quotations.requst_quotation.get_item_suppliers_with_email",
