frappe.ui.form.on('Stock Entry', {
    async refresh(frm) {
        if (
            frm.doc.docstatus === 0 &&
            frm.doc.purpose === "Material Transfer"
        ) {
            // Get user's default warehouse
            let defaultWarehouse = await frappe.call({
                method: "gormsolutions_mobile_app.custom_api.stock.stock_transfer_setting.get_user_default_warehouse"
            }).then(r => r.message);

            if (!frm.doc.custom_approve_status && defaultWarehouse) {
                // Check if any item's source warehouse matches the user's default warehouse
                const has_same_source = (frm.doc.items || []).some(
                    item => item.s_warehouse === defaultWarehouse
                );

                // Only show the buttons if user's default warehouse is NOT the source warehouse
                if (!has_same_source) {
                    // Approve Transfer with accepted qty input
                    frm.add_custom_button(__('Approve Transfer'), function () {
                        const fields = frm.doc.items.map((row, idx) => ({
                            label: `Accepted Qty for ${row.item_name} (${row.item_code})`,
                            fieldname: `accepted_qty_${idx}`,
                            fieldtype: 'Float',
                            reqd: 1,
                            default: row.qty
                        }));

                        frappe.prompt(fields, function (values) {
                            const accepted_qty_map = {};

                            frm.doc.items.forEach((row, idx) => {
                                const accepted_qty = values[`accepted_qty_${idx}`];
                                accepted_qty_map[row.name] = accepted_qty;
                            });

                            frappe.call({
                                method: "gormsolutions_mobile_app.custom_api.stock.stock_transfer_setting.approve_stock_entry",
                                args: {
                                    docname: frm.doc.name,
                                    accepted_qtys: accepted_qty_map
                                },
                                callback: function () {
                                    frappe.msgprint("Stock Entry has been approved.");
                                    frm.reload_doc();
                                }
                            });
                        }, __('Enter Accepted Quantities'), __('Approve'));
                    }, __('Actions'));

                    // Reject Transfer
                    frm.add_custom_button(__('Reject Transfer'), function () {
                        frappe.prompt(
                            [
                                {
                                    label: 'Reason for Rejection',
                                    fieldname: 'reason',
                                    fieldtype: 'Small Text',
                                    reqd: 1
                                }
                            ],
                            function (values) {
                                frappe.call({
                                    method: "gormsolutions_mobile_app.custom_api.stock.stock_transfer_setting.reject_stock_entry",
                                    args: {
                                        docname: frm.doc.name,
                                        reason: values.reason
                                    },
                                    callback: function () {
                                        frappe.msgprint("Stock Entry has been rejected.");
                                        frm.reload_doc();
                                    }
                                });
                            },
                            __('Reject Transfer'),
                            __('Submit')
                        );
                    }, __('Actions'));
                }
            }

            // Status indicator
            if (frm.doc.custom_approve_status === "Rejected") {
                frm.page.set_indicator("Rejected", "red");
            } else if (frm.doc.custom_approve_status === "Approved") {
                frm.page.set_indicator("Approved", "green");
            } else {
                frm.page.set_indicator("Pending Approval", "orange");
            }
        }
    }
});

