frappe.ui.form.on('Station Print Setting', {
    refresh(frm) {
        frm.add_custom_button('Download Customers CSV', async function () {
            const headers = [
                'customer_name', 'name', 'mobile_no', 'email_id',
                'creation', 'loyalty_program', 'earned_points',
                'redeemed_points', 'remaining_points', 'conversion_rate',
                'redeemed_value', 'remaining_value'
            ];

            const limit = 1500;
            let offset = 0;
            let all_data = [];
            let total_downloaded = 0;
            const estimated_total = 193525;

            // Show progress dialog
            let progress_dialog = frappe.msgprint({
                title: __('Downloading CSV'),
                indicator: 'blue',
                message: `
                    <div style="margin-top:10px">
                        <div class="progress mb-2">
                            <div class="progress-bar progress-bar-striped progress-bar-animated" 
                                 role="progressbar" 
                                 style="width: 0%;" 
                                 id="csv-progress-bar">0%</div>
                        </div>
                        <div id="csv-status-text">
                            Downloaded: 0 / ${estimated_total}<br>
                            Remaining: ${estimated_total}
                        </div>
                    </div>`,
                wide: true,
                primary_action: () => {},
            });

            while (true) {
                const result = await frappe.call({
                    method: 'gormsolutions_mobile_app.custom_api.customer.get_customer_details',
                    args: { limit, offset }
                });

                const batch = result.message;

                if (!batch || batch.length === 0) {
                    break; // no more data
                }

                all_data.push(...batch);
                offset += limit;
                total_downloaded += batch.length;

                // Update progress UI
                const percent = Math.min(Math.floor((total_downloaded / estimated_total) * 100), 100);
                const bar = document.getElementById('csv-progress-bar');
                const text = document.getElementById('csv-status-text');

                if (bar) {
                    bar.style.width = percent + '%';
                    bar.innerText = percent + '%';
                }

                if (text) {
                    text.innerHTML = `
                        Downloaded: ${total_downloaded.toLocaleString()} / ${estimated_total.toLocaleString()}<br>
                        Remaining: ${(estimated_total - total_downloaded).toLocaleString()}
                    `;
                }

                // Short delay to prevent UI freezing
                await new Promise(resolve => setTimeout(resolve, 150));
            }

            // Create CSV
            let csv = headers.join(',') + '\n';
            all_data.forEach(customer => {
                const row = headers.map(h => customer[h] || '');
                csv += row.map(val => `"${val}"`).join(',') + '\n';
            });

            // Trigger download
            const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
            const link = document.createElement('a');
            link.href = URL.createObjectURL(blob);
            link.download = 'customer_details.csv';
            document.body.appendChild(link);
            link.click();
            document.body.removeChild(link);

            frappe.msgprint(__('✅ CSV Download Complete — Total records: ' + total_downloaded.toLocaleString()));
        });
    }
});

frappe.ui.form.on('Station Print Setting', {
