                primary_action: () => {},
            });

            while (true) {
                const result = await frappe.call({
                    method: 'gormsolutions_mobile_app.custom_api.item.get_item_details',
                    args: { limit, offset }
                });

                const batch = result.message;
                if (!batch || batch.length === 0) {
                    break;
